// Runs BEFORE OAuthValidateRequest (token endpoint only).
if (context.get('api.operation.path') === '/oauth2/token') {
  // Define dynamic scope prefixes here (e.g., ['consent'] or ['consent', 'payment'])
  var DYNAMIC_PREFIXES = ['consent'];

console.error("**** SCOPES: " + context.get('oauth.settings.allowed_scopes'));

  var raw = context.get('request.parameters.scope.values[0]');
  var requested = decodeURIComponent(String(raw || '').replace(/\+/g, ' '))
    .split(/\s+/).filter(Boolean);

  var dynamicMatches = [];
  var processed = requested.map(function (s) {
    for (var i = 0; i < DYNAMIC_PREFIXES.length; i++) {
      var prefix = DYNAMIC_PREFIXES[i] + ':';
      // Matches "consent:1234", "consent:<uuid>", but not "consent" or "consent:*"
      if (s.indexOf(prefix) === 0 && s.length > prefix.length && s !== (prefix + '*')) {
        dynamicMatches.push(s);
        return prefix + '*'; // Replaces "consent:1234" with "consent:*"
      }
    }
    return s;
  });

  if (dynamicMatches.length > 0) {
    // Store original dynamic scope(s) for restoration before token generation
    context.set('consent.requested', dynamicMatches.join(' '));
    // Set placeholder scope(s) for OAuthValidateRequest
    context.set('oauth.processing.scope', processed.join(' '));
  }
}

// Runs right BEFORE OAuthGenerateAccessToken.
// The advanced scope check has run by now. Put the real dynamic scope(s) back so
// they are written into the access token, next to the placeholder consent:*.
console.error("**** SCOPES AFTER: " + context.get('oauth.settings.allowed_scopes'));


var requested = context.get('consent.requested');
if (requested) {
  var parts = String(requested).split(' ');
  if (parts.indexOf('consent:*') === -1) parts.push('consent:*');
  context.set('oauth.processing.scope', parts.join(' '));
}

/*
  Application Scope Check
    - extension that allows the flexibility to check and override what scope the 
      application is allowed
*/
var urlopen = require ('urlopen');

// Check User Security Context
let authscope = context.get('user.au.responseheaders.x-selected-scope');
if (authscope) 
    context.set('oauth.processing.scope', authscope);

// Client Context
let apiObj = context.get('api');
// Client Context
let clientObj = context.get('client');
// OAuth Context
let oauthObj = context.get('oauth');
// Session Context
let sessionObj = context.get('session');

let grant_type = oauthObj.processing.grant_type;

if(grant_type !== 'authorization_code') {

  //from set-variable action
  //example: https://9.70.00.00:9443/org/sandbox/loopback/advscope
  const URL = context.get('oauth.advscope.app.url');

  //from set-variable action
  const CustomTLSProfile = context.get('oauth.advscope.app.tls-profile');

  //default example: 'tls-client-profile-catalog-default'
  //full name in log: 'kenorg_sandbox_tlsp-tls-client-profile-catalog-defaultV1.0.0'
  let DefaultTLSProfile = 'tls-client-profile-catalog-default';

  let headerName = { };

  // Check if query already exists
  let query = '&';
  if (URL.indexOf('?') == -1)
    query = '?';

  query += 'app_name=' + encodeURIComponent(clientObj.app.name) + '&' +
        'app_id=' + encodeURIComponent(clientObj.app.id) + '&' +
        'org=' + encodeURIComponent(clientObj.org.name) + '&' +
        'org_id=' + encodeURIComponent(clientObj.org.id) + '&' +
        'catalog=' + encodeURIComponent(apiObj.catalog.name) + '&' +
        'catalog_id=' + encodeURIComponent(apiObj.catalog.id) + '&' +
        'trans_id=' + encodeURIComponent(sessionObj.transactionID) + '&' +
        'token_scope=' + encodeURIComponent(oauthObj.processing.scope) + '&' +
        'api_scope=' + encodeURIComponent(oauthObj.settings.allowed_scopes);


  // define urlopen user agent options
  let ua_options = {
      'persistentConnection': false,
      'allowCompression': false,
      'followRedirect': false,
      'http10Only': false,
      'rewriteHost': false
  };
  let httpUA = new urlopen.HttpUserAgent(ua_options);

  // define the urlopen options
  let options = {
      target: URL + query,
      sslClientProfile: CustomTLSProfile ? CustomTLSProfile : DefaultTLSProfile,
      method: 'get',
      headers: headerName,
      timeout: 60,
      agent: httpUA
  };

  // open connection to advance scope endpoint
  urlopen.open (options, function (error, response) {
      if (error) {
          // Error failed to connect
          context.set('oauth.custom_error.status.code', 500);
          context.set('oauth.custom_error.status.reason', 'Internal Server Error');
          context.set('oauth.custom_error.message', 'server_error');
          context.set('oauth.custom_error.description', 'Advanced Scope failed to connect');
      } else {
          var responseStatusCode = response.statusCode;
          if (responseStatusCode == 200 ) {
            // Set selected scope
              let selectedScope = response.get('x-selected-scope');
              if (selectedScope)
                context.set('oauth.processing.scope', selectedScope);
          } else {
              // Error non 200 response
              context.set('oauth.custom_error.message', 'invalid_scope');
              context.set('oauth.custom_error.description', 'Advanced Scope recieved a non 200 response');
          }
      }
  });
}
